import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        // last[mask] = smallest last value of an increasing subsequence whose OR is mask (1024 = unreachable).
        int[] last = new int[1024];
        Arrays.fill(last, 1024);
        last[0] = 0;
        for (int i = 0; i < n; i++) {
            int v = nextInt();
            for (int mask = 0; mask < 1024; mask++)
                if (last[mask] < v) last[mask | v] = Math.min(last[mask | v], v);
        }
        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (int i = 0; i < 1024; i++) {
            if (last[i] < 1024) {
                if (count++ > 0) sb.append(' ');
                sb.append(i);
            }
        }
        System.out.println(count);
        System.out.println(sb);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	// last[mask] = smallest last value of an increasing subsequence whose OR is mask (1024 = unreachable).
	last := make([]int, 1024)
	for i := range last {
		last[i] = 1024
	}
	last[0] = 0
	for i := 0; i < n; i++ {
		v := nextInt()
		for mask := 0; mask < 1024; mask++ {
			if last[mask] < v && v < last[mask|v] {
				last[mask|v] = v
			}
		}
	}
	result := []string{}
	for i := 0; i < 1024; i++ {
		if last[i] < 1024 {
			result = append(result, strconv.Itoa(i))
		}
	}
	fmt.Println(len(result))
	fmt.Println(strings.Join(result, " "))
}
